INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56439, 0, 0, 'Die or surrender. You cannot defeat me.', 14, 0, 100, 0, 0, 28273, 'Sha of Doubt'),
(56439, 1, 0, 'You cannot escape me. I am... in... every...  breath...', 14, 0, 100, 0, 0, 28274, 'Sha of Doubt'),
(56439, 2, 0, 'See how effortlessly you become unraveled.', 14, 0, 100, 0, 0, 28275, 'Sha of Doubt'),
(56439, 2, 1, 'Succumb to the darkness inside your soul.', 14, 0, 100, 0, 0, 28276, 'Sha of Doubt'),
(56439, 3, 0, 'All is lost.', 14, 0, 100, 0, 0, 28277, 'Sha of Doubt'),
(56439, 4, 0, 'Abandon all hope.', 14, 0, 100, 0, 0, 28278, 'Sha of Doubt'),
(56439, 4, 1, 'Embrace your despair.', 14, 0, 100, 0, 0, 28279, 'Sha of Doubt');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56448, 0, 0, 'The water reacts violently to your touch!', 41, 0, 100, 0, 0, 0, 'Wise Mari'),
(56448, 1, 0, 'You dare to disturb these waters? You will drown!', 12, 0, 100, 0, 0, 28257, 'Wise Mari'),
(56448, 2, 0, 'Rise!', 12, 0, 100, 0, 0, 28260, 'Wise Mari'),
(56448, 2, 1, 'Spring to life!', 12, 0, 100, 0, 0, 28258, 'Wise Mari'),
(56448, 2, 2, 'Living water, bring them death!', 12, 0, 100, 0, 0, 28261, 'Wise Mari'),
(56448, 2, 3, 'Do not run, it only delays the inevitable.', 12, 0, 100, 0, 0, 28269, 'Wise Mari'),
(56448, 2, 4, 'Come in, the water\'s fine!', 12, 0, 100, 0, 0, 28270, 'Wise Mari'),
(56448, 2, 5, 'Let death wash over you!', 12, 0, 100, 0, 0, 28271, 'Wise Mari'),
(56448, 3, 0, 'Behold the power of torrential waters!', 12, 0, 100, 0, 0, 28266, 'Wise Mari'),
(56448, 4, 0, '%s draws from the surrounding water!', 41, 0, 100, 0, 0, 0, 'Wise Mari'),
(56448, 5, 0, 'The darkness clears...', 12, 0, 100, 0, 0, 28262, 'Wise Mari'),
(56448, 6, 0, 'I peer into these waters and my reflection is empty...', 12, 0, 100, 0, 0, 28263, 'Wise Mari'),
(56448, 7, 0, 'Waters... claim me...', 12, 0, 100, 0, 0, 28264, 'Wise Mari'),
(56448, 8, 0, 'Your cause is hopeless.', 12, 0, 100, 0, 0, 28268, 'Wise Mari'),
(56448, 8, 1, 'As the waters foretold.', 12, 0, 100, 0, 0, 28267, 'Wise Mari');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56511, 0, 0, '%s rises from the fountain!', 41, 0, 100, 0, 0, 0, 'Corrupt Living Water');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56732, 0, 0, 'The heart of the Great Serpent will not fall into your hands!', 14, 0, 100, 0, 0, 27603, 'Liu Flameheart'),
(56732, 1, 0, 'The haze has been lifted from my eyes... forgive me for doubting you...', 14, 0, 100, 0, 0, 27604, 'Liu Flameheart'),
(56732, 2, 0, 'Jade Serpent, grant me strength!', 14, 0, 100, 0, 0, 27605, 'Liu Flameheart'),
(56732, 3, 0, 'The cycle must continue, the Jade Serpent must be reborn!', 14, 0, 100, 0, 0, 27606, 'Liu Flameheart'),
(56732, 4, 0, 'Leave this place.', 14, 0, 100, 0, 0, 27609, 'Liu Flameheart to Ã°Ã†Ã°Â¥Ã°â•£ÃÃ¼Ã°â•‘Ã°Â¥ Ã°â•Ã°ÃÃÃ‡ÃÃ©Ã°â–“ÃÃ¯ÃÃ '),
(56732, 4, 1, 'The heart is MINE!', 14, 0, 100, 0, 0, 27608, 'Liu Flameheart'),
(56732, 5, 0, 'Your forces are weak!', 14, 0, 100, 0, 0, 27607, 'Liu Flameheart');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56762, 0, 0, 'Be free of doubt, priestess...', 14, 0, 100, 0, 0, 28559, 'Yu\'lon');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56843, 0, 0, 'You there! In the rafters! My sacred library has become possessed by the Sha!', 14, 0, 100, 0, 0, 30887, 'Lorewalker Stonestep'),
(56843, 1, 0, 'See how they pour from every letter of these sacred scrolls... corrupting them! Defiling them!', 14, 0, 100, 0, 0, 30888, 'Lorewalker Stonestep'),
(56843, 2, 0, 'I beseech you, kind strangers. Cleanse this place of their foul presence! Lay our stories to rest!', 14, 0, 100, 0, 0, 30889, 'Lorewalker Stonestep'),
(56843, 3, 0, 'You must destroy the source of the corruption! Quickly, before our cherished history is erased forever!', 14, 0, 100, 0, 0, 30890, 'Lorewalker Stonestep'),
(56843, 4, 0, 'Oh, my. If I am not mistaken, it appears that the tale of Zao Sunseeker has come to life before us.', 14, 0, 100, 0, 0, 30901, 'Lorewalker Stonestep'),
(56843, 5, 0, 'According to the legend, long ago, there were five suns that burned brightly in the sky. When the winds blew, their intense heat caused great wildfires.', 14, 0, 100, 0, 0, 30902, 'Lorewalker Stonestep'),
(56843, 6, 0, 'Crops wilted, villages burned, and families wandered endlessly to seek refuge from the flames...', 14, 0, 100, 0, 0, 30903, 'Lorewalker Stonestep'),
(56843, 7, 0, 'The fires, they are burning the library! Please, heroes! Purge this evil before the temple crumbles to ash!', 14, 0, 100, 0, 0, 30904, 'Lorewalker Stonestep'),
(56843, 8, 0, 'Zao has become corrupted too! Please, fight him with dignity...', 14, 0, 100, 0, 0, 30906, 'Lorewalker Stonestep'),
(56843, 9, 0, 'Ah, it is not yet over. From what I see, we face the trial of the yaungol. Let me shed some light...', 14, 0, 100, 0, 0, 30896, 'Lorewalker Stonestep'),
(56843, 10, 0, 'As the tale goes, the yaungol was traveling across the Kun\'lai plains when suddenly he was ambushed by two strange creatures!', 14, 0, 100, 0, 0, 30897, 'Lorewalker Stonestep'),
(56843, 11, 0, 'The yaungol attacked the beasts with great determination and ferocity. Yet, the more he attacked, the more fearsome the beasts grew!', 14, 0, 100, 0, 0, 30898, 'Lorewalker Stonestep'),
(56843, 12, 0, 'However, when he let it alone, the beast shrank to near nothingness.', 14, 0, 100, 0, 0, 30899, 'Lorewalker Stonestep'),
(56843, 13, 0, 'For you see, strife feeds on conflict. When you have peace in your heart, strife will find somewhere else to roam.', 14, 0, 100, 0, 0, 30900, 'Lorewalker Stonestep');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(58826, 0, 0, 'I can allow this no longer!', 14, 0, 100, 0, 0, 27747, 'Zao Sunseeker'),
(58826, 1, 0, 'The blistering heat must have dulled my senses... mirages! All of you!', 14, 0, 100, 0, 0, 27748, 'Zao Sunseeker');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(59546, 0, 0, 'When man asks favor of a fish...', 12, 0, 100, 0, 0, 0, ''),
(59546, 1, 0, '\'Tis hard to decipher his true wish...', 12, 0, 100, 0, 0, 0, ''),
(59546, 2, 0, 'He often seeks a lordly dish...', 12, 0, 100, 0, 0, 0, ''),
(59546, 3, 0, 'To serve upon his table.', 12, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(72726, 0, 0, 'Ah, new customers. Welcome!', 14, 0, 100, 0, 0, 0, ''),
(72726, 1, 0, 'Leaving so soon? Do come again!', 14, 0, 100, 0, 0, 0, ''),
(72726, 2, 0, 'Time to close already? Well, I guess I should get home to Chao-Wei.', 14, 0, 100, 0, 0, 0, ''),
(72726, 3, 0, 'The secret to good noodle soup begins with strong, thick noodles!', 14, 0, 100, 0, 0, 0, ''),
(72726, 4, 0, 'The soup must be piping hot to warm the soul!', 14, 0, 100, 0, 0, 0, '');
